name = "Legacy_API_1.30";
author = "Rook";
overview = "Restores vanilla script API that DayZ 1.30 removed or renamed, where 1.30 has an exact equivalent, so mods written for 1.29 compile again: CombinationLock.UnlockServer, CarScript.ToggleHeadlights, Ammo_40mm_Explosive.ShootsExplosiveAmmo, CachedEquipmentItemAttribute.HasParent, Fence.ATTSLOT_*, ItemBase.m_ItemModelLength/m_ItemAttachOffset. Does nothing on 1.29.";
